// 打孔海报 · 酒馆助手版
(() => {
  const window = globalThis.parent && globalThis.parent !== globalThis ? globalThis.parent : globalThis;
  const document = window.document;
  const { Image, FontFace, MutationObserver, SillyTavern, Path2D, DOMMatrix } = window;
  const requestAnimationFrame = window.requestAnimationFrame.bind(window);

  if (typeof window.__pkDispose === 'function') window.__pkDispose();
  document.getElementById('pk-style')?.remove();
  const style = document.createElement('style');
  style.id = 'pk-style';
  // Stylesheet consolidated from historical CSS append patches; original cascade order preserved.
  // The build step embeds src/styles/panel.css in dist/repo美化.json.
  // Keep CSS separate from application logic; dist remains standalone.
  style.textContent = "#pk-overlay{--pk-bg:#fff;--pk-fg:#171717;--pk-mute:#858585;--pk-line:#ececec;--pk-soft:#f6f6f6;--pk-card:#fff;--pk-stage-h:59dvh;--pk-stage-h2:46dvh;--pk-panel-h:22dvh;position:fixed;inset:0;z-index:100000;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,.48);color:var(--pk-fg);font:400 14px/1.45 -apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Helvetica Neue",sans-serif;letter-spacing:0;text-shadow:none;-webkit-font-smoothing:antialiased;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
@media (prefers-color-scheme:dark) {
  #pk-overlay { --pk-bg:#161616; --pk-fg:#f4f4f4; --pk-mute:#959595;
    --pk-line:#303030; --pk-soft:#232323; --pk-card:#202020; background:rgba(0,0,0,.75); }
}
#pk-overlay.show{display:flex}
#pk-overlay *{box-sizing:border-box}
#pk-overlay [hidden]{display:none!important}
#pk-overlay input,#pk-overlay textarea{-webkit-user-select:text;user-select:text;-webkit-touch-callout:default }
#pk-overlay .pk-modal{overflow:hidden;background:var(--pk-bg);border-radius:18px;box-shadow:0 22px 90px rgba(0,0,0,.22)}
#pk-overlay .pk-head{flex:none;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--pk-line)}
#pk-overlay .pk-head>b{font-size:15px;font-weight:650;letter-spacing:-.025em}
#pk-overlay .pk-hr{display:flex;align-items:center;gap:7px}
#pk-overlay .pk-ic{width:36px;height:36px;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:16px;color:var(--pk-fg);cursor:pointer;touch-action:manipulation}
#pk-overlay .pk-ic:active{background:var(--pk-soft)}
#pk-overlay .pk-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:0 13px;border:1px solid var(--pk-line);border-radius:10px;background:var(--pk-card);color:var(--pk-fg);font-weight:550;white-space:nowrap;cursor:pointer;box-shadow:none;touch-action:manipulation}
#pk-overlay .pk-btn:active{opacity:.68}
#pk-overlay .pk-btn.pk-pri{background:var(--pk-fg);color:var(--pk-bg);border-color:var(--pk-fg);font-weight:650}
#pk-overlay .pk-btn.pk-ghost{border-color:transparent;background:transparent;color:var(--pk-mute)}
#pk-overlay .pk-stage{flex:none;position:relative;height:var(--pk-stage-h);min-height:90px;display:flex;align-items:center;justify-content:center;margin:0;padding:17px 18px 13px;background:var(--pk-soft);transition:height .2s ease}
#pk-overlay.panel .pk-stage{height:var(--pk-stage-h2)}
#pk-overlay .pk-stage canvas{display:block;max-width:100%;max-height:100%;width:auto;height:auto;border-radius:1px;box-shadow:0 3px 22px rgba(0,0,0,.10)}
#pk-overlay .pk-stage canvas{cursor:crosshair}
#pk-overlay .pk-edta{display:none;position:absolute;margin:0;padding:0;border:0;outline:0;resize:none;border-radius:0;background:transparent;color:inherit;box-shadow:none!important;-webkit-appearance:none;appearance:none;overflow:auto;overflow-wrap:anywhere;white-space:pre-wrap;scrollbar-width:thin}
#pk-overlay .pk-preview-tools .pk-btn{border:0;padding:0;font-size:12.5px;background:transparent}
#pk-overlay .pk-preview-tools .pk-btn i{font-size:12px}
#pk-overlay .pk-tabs{display:grid;gap:6px}
#pk-overlay .pk-tabs b{position:relative;min-width:0;display:flex;align-items:center;justify-content:center;cursor:pointer;color:var(--pk-mute);transition:color .14s;white-space:nowrap}
#pk-overlay .pk-tabs b.on{color:var(--pk-fg)}
#pk-overlay .pk-tabs b.on::after{content:"";position:absolute;bottom:0;left:25%;right:25%;height:2px;background:var(--pk-fg);border-radius:2px}
#pk-overlay .pk-panel{flex:none;order:2;height:0;overflow-y:auto;overscroll-behavior:contain;border-top:0 solid var(--pk-line);background:var(--pk-bg);transition:height .18s ease;scrollbar-width:thin}
#pk-overlay.panel .pk-panel{border-top-width:1px}
#pk-overlay .pk-pane{display:none}
#pk-overlay .pk-pane.on{display:block}
#pk-overlay .pk-grp{border-bottom:1px solid var(--pk-line)}
#pk-overlay .pk-grp:last-child{border-bottom:0}
#pk-overlay .pk-grp header{display:flex;align-items:center;cursor:pointer;color:var(--pk-fg);font-weight:650;letter-spacing:0}
#pk-overlay .pk-grp header span{flex:1}
#pk-overlay .pk-arrow{font-size:10px;color:var(--pk-mute);transition:transform .15s}
#pk-overlay .pk-grp.open .pk-arrow{transform:rotate(180deg)}
#pk-overlay .pk-grp-b{display:none;padding:0 0 16px}
#pk-overlay .pk-grp.open .pk-grp-b{display:block}
#pk-overlay .pk-row{display:flex;align-items:center}
#pk-overlay .pk-row.pk-btns{min-height:0;flex-wrap:wrap;gap:8px}
#pk-overlay .pk-tgrow{justify-content:space-between}
#pk-overlay .pk-l{flex:none;min-width:57px;color:var(--pk-mute)}
#pk-overlay .pk-note{color:var(--pk-mute);font-size:11.5px;line-height:1.65;padding:6px 0 2px}
#pk-overlay .pk-sub{font-size:11.5px;color:var(--pk-mute);margin:6px 0}
#pk-overlay .pk-in{flex:1;min-width:0;height:35px;margin:0;padding:0 11px;border:1px solid var(--pk-line);border-radius:9px;background:var(--pk-soft);color:var(--pk-fg);font:400 13px/1.4 inherit;outline:0;box-shadow:none}
#pk-overlay .pk-in:focus{border-color:var(--pk-fg)}
#pk-overlay .pk-in::placeholder{color:var(--pk-mute)}
#pk-overlay .pk-sl{flex:1;position:relative;height:34px;cursor:pointer;touch-action:none}
#pk-overlay .pk-sl-tr{position:absolute;inset:50% 0 auto;height:2px;margin-top:-1px;background:var(--pk-line);border-radius:2px;overflow:hidden}
#pk-overlay .pk-sl-fill{height:100%;background:var(--pk-fg)}
#pk-overlay .pk-sl-th{position:absolute;top:50%;width:15px;height:15px;margin:-7.5px 0 0 -7.5px;border-radius:50%;background:var(--pk-fg);border:2px solid var(--pk-bg);box-shadow:0 0 0 1px var(--pk-fg)}
#pk-overlay .pk-v{flex:none;width:36px;text-align:right;font-size:12px;color:var(--pk-fg);font-variant-numeric:tabular-nums}
#pk-overlay .pk-seg{flex:1;display:flex;gap:2px;padding:3px;border-radius:10px;background:var(--pk-soft)}
#pk-overlay .pk-seg b{flex:1;min-width:0;height:29px;display:flex;align-items:center;justify-content:center;white-space:nowrap;border-radius:7px;font-weight:450;color:var(--pk-mute);cursor:pointer}
#pk-overlay .pk-seg b.on{background:var(--pk-card);color:var(--pk-fg);font-weight:650;box-shadow:0 1px 4px rgba(0,0,0,.06)}
#pk-overlay .pk-tg{position:relative;flex:none;width:39px;height:23px;border-radius:30px;background:#d7d7d7;cursor:pointer;transition:background .14s}
#pk-overlay .pk-tg i{position:absolute;top:2px;left:2px;width:19px;height:19px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.15);transition:transform .14s}
#pk-overlay .pk-tg.on{background:#262626}
#pk-overlay .pk-tg.on i{transform:translateX(16px)}
#pk-overlay .pk-cols{display:flex;flex-wrap:wrap}
#pk-overlay .pk-col{position:relative;display:flex;align-items:center;gap:7px;font-size:12.5px;cursor:pointer}
#pk-overlay .pk-col input{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
#pk-overlay .pk-col span{width:23px;height:23px;border:1px solid rgba(0,0,0,.12);border-radius:50%;box-shadow:0 0 0 2px var(--pk-bg)}
#pk-overlay .pk-col em{font-style:normal;color:var(--pk-mute)}
#pk-overlay .pk-pick{display:grid;grid-template-columns:repeat(auto-fill,minmax(48px,1fr))}
#pk-overlay .pk-pick b{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;font-weight:400}
#pk-overlay .pk-pick b i{width:39px;height:39px;background-size:cover;border-radius:8px;box-shadow:inset 0 0 0 1px rgba(0,0,0,.07)}
#pk-overlay .pk-pick.pk-shapes b i{background-color:var(--pk-soft);background-size:100%;box-shadow:none}
@media (prefers-color-scheme:dark) {#pk-overlay .pk-pick.pk-shapes b i {filter:invert(1) brightness(1.35); background-color:#ddd}}
#pk-overlay .pk-pick b span{font-size:10.5px;color:var(--pk-mute)}
#pk-overlay .pk-pick b.on i{outline:2px solid var(--pk-fg);outline-offset:2px}
#pk-overlay .pk-pick b.on span{color:var(--pk-fg);font-weight:650}
#pk-overlay .pk-fonts b{display:flex;align-items:center;justify-content:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:1px solid var(--pk-line);border-radius:9px;background:var(--pk-card);font-weight:450;cursor:pointer}
#pk-overlay .pk-fonts b.on{border-color:var(--pk-fg);box-shadow:inset 0 0 0 1px var(--pk-fg)}
#pk-overlay .pk-step{display:inline-flex;align-items:center;height:34px;border:1px solid var(--pk-line);border-radius:10px;background:var(--pk-card)}
#pk-overlay .pk-step b{width:29px;text-align:center;font-size:17px;font-weight:400;cursor:pointer}
#pk-overlay .pk-cnt{min-width:20px;text-align:center;font-size:12.5px;font-weight:650;font-variant-numeric:tabular-nums}
#pk-overlay .pk-rep{display:flex;align-items:center;gap:6px;padding:4px 0}
#pk-overlay .pk-rep>i{font-size:10px;color:var(--pk-mute)}
#pk-overlay .pk-repf{position:relative;flex:1;min-width:0;display:flex}
#pk-overlay .pk-repf em{position:absolute;right:8px;top:50%;transform:translateY(-50%);font-size:10px;color:var(--pk-mute);font-style:normal;pointer-events:none}
#pk-overlay .pk-rep b{flex:none;display:flex;align-items:center;justify-content:center;width:24px;height:28px;color:var(--pk-mute);font-size:11px;cursor:pointer}
#pk-overlay .pk-chips{display:flex;flex-wrap:wrap;gap:7px;padding:9px 0 14px}
#pk-overlay .pk-chip{display:inline-flex;align-items:center;gap:6px;min-height:34px;padding:0 12px;border:1px solid var(--pk-line);border-radius:9px;font-size:12.5px;cursor:pointer}
#pk-overlay .pk-chip:active{opacity:.7}
#pk-overlay .pk-chip i{font-size:10px;color:var(--pk-mute);padding:4px;margin-right:-5px}

#pk-overlay .pk-tabs {grid-template-columns:repeat(3,minmax(0,1fr))}
#pk-overlay .pk-pane {padding:4px clamp(12px,3.6vw,18px) 14px}
#pk-overlay .pk-grp header {height:43px;min-height:43px}
#pk-overlay .pk-grp-b {padding-bottom:10px}
#pk-overlay .pk-row {min-height:38px;gap:8px}
#pk-overlay .pk-row.pk-btns {padding:5px 0}
#pk-overlay .pk-cols {gap:10px;padding:6px 0}
#pk-overlay .pk-pick {gap:7px 5px;padding:7px 0}
#pk-overlay .pk-img-adjust {margin:2px 0 5px}
#pk-overlay .pk-settings-head {height:34px;justify-content:flex-end;padding:0 12px}
#pk-overlay .pk-settings-head>span {display:none}
#pk-overlay .pk-settings-layer .pk-kb-done {display:none}
#pk-overlay.pk-keyboard .pk-settings-layer .pk-kb-done {display:inline-flex}

#pk-overlay .pk-sig-presets{margin-top:10px;padding-top:6px;border-top:1px solid var(--pk-line)}
#pk-overlay .pk-sig-presets .pk-chips{padding:4px 0 8px}




/* v19: condensed font categories and image-only theme thumbnails. */
#pk-overlay .pk-font-tabs{margin:2px 0 9px}
#pk-overlay .pk-font-tabs button{border:1px solid var(--pk-line);border-radius:8px;background:var(--pk-card);color:var(--pk-fg);font:inherit;font-size:11px;cursor:pointer}
#pk-overlay .pk-font-tabs button.on{border-color:var(--pk-fg);font-weight:650}
#pk-overlay .pk-fonts [hidden]{display:none!important}
#pk-overlay .pk-tpl-grid .pk-tpl-card{aspect-ratio:0.78;min-height:0;border-radius:8px}
#pk-overlay .pk-tpl-grid .pk-tpl-card:active{opacity:.8}
#pk-overlay .pk-tpl-grid .pk-tpl-del{position:absolute;top:0;right:0;display:flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:0 7px 0 7px;background:rgba(0,0,0,.62);color:#fff;font:500 15px/1 sans-serif;z-index:2}




#pk-overlay .pk-skin-list{display:flex;flex-direction:column;gap:0;padding-bottom:8px}
#pk-overlay .pk-skin-list button{display:flex;align-items:center;gap:8px;padding:11px 6px;background:transparent;color:var(--pk-fg);border:0;border-bottom:1px solid var(--pk-line);font:inherit;font-size:13px;text-align:left;cursor:pointer}
#pk-overlay .pk-skin-list button .pk-skin-name{font-weight:570;flex:1}
#pk-overlay .pk-skin-list button small{font-size:11px;color:var(--pk-mute)}
#pk-overlay .pk-skin-list button i{font-size:13px;visibility:hidden}
#pk-overlay .pk-skin-list button.on i{visibility:visible}
#pk-overlay .pk-skin-list button.on .pk-skin-name{font-weight:750}
#pk-overlay .pk-skin-list [hidden]{display:none!important}

/* v23: editing and drawer are mutually exclusive on iOS. */
#pk-overlay .pk-skin-list-flat{padding-top:0}
#pk-overlay .pk-skin-list-flat button{min-height:44px}
#pk-overlay .pk-pane[data-pane="punch"] .pk-sub{font-weight:600;margin:13px 0 4px}
#pk-overlay .pk-pane[data-pane="punch"] .pk-sub:first-child{margin-top:4px}

#pk-overlay.css-active .pk-stage canvas {display:none!important}
#pk-overlay .pk-css-holder {display:none; flex:none; position:relative; margin:0 auto; padding:0; overflow:visible; max-width:none; box-shadow:0 3px 22px rgba(0,0,0,.10);background:#fff}
#pk-overlay.css-active .pk-css-holder {display:block}
#pk-overlay .pk-css-holder .pk-css-page {position:absolute;top:0;left:0;width:390px;transform-origin:top left}
#pk-overlay .pk-css-manager {display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:10px 0}
#pk-overlay .pk-css-manager .pk-btn {min-height:33px}
#pk-overlay .pk-css-list [data-cssdel] {flex:none;padding:4px 9px;border:1px solid var(--pk-line);border-radius:8px;cursor:pointer;color:var(--pk-mute);font-size:12px}
#pk-overlay .pk-css-item {display:flex;gap:6px;align-items:center}
#pk-overlay .pk-css-item [data-skin] {flex:1;min-width:0}

/* v37 mobile toolbar: three fixed actions on ONE row, never wrap. */
#pk-overlay .pk-preview-tools{display:flex!important;flex-wrap:nowrap!important;align-items:center}
#pk-overlay .pk-zoom-tools{flex:0 0 auto;gap:0;min-width:0}
#pk-overlay .pk-zoom-tools .pk-tool{min-width:27px!important;width:27px!important;padding:0!important}
#pk-overlay .pk-zoom-tools [data-act="zoom-reset"]{width:37px!important;min-width:37px!important}
#pk-overlay .pk-main-tools{flex:1 1 auto;min-width:0;display:flex!important;flex-wrap:nowrap!important;gap:0!important}
#pk-overlay .pk-main-tools .pk-tool{flex:1 1 0;min-width:0!important;width:auto!important;padding:0 2px!important;gap:3px!important;white-space:nowrap;height:42px;font-size:11px!important}
#pk-overlay .pk-main-tools .pk-tool span{font-size:11px!important;white-space:nowrap;display:inline!important}
#pk-overlay .pk-main-tools .pk-tool i{font-size:13px!important;flex:none}
#pk-overlay .pk-preview-tools .pk-cat-tools{display:none!important}
#pk-overlay .pk-css-holder{-webkit-user-select:none!important;user-select:none!important;-webkit-touch-callout:none!important}
@media(max-width:520px){#pk-overlay .pk-main-tools .pk-tool{font-size:10.5px!important}#pk-overlay .pk-main-tools .pk-tool span{font-size:10.5px!important}}

/* v38: one-line swipe galleries with real color input still available. */
#pk-overlay .pk-font-tabs{display:flex!important;grid-template-columns:none!important;gap:7px!important;overflow-x:auto!important;overflow-y:hidden!important;white-space:nowrap!important;scrollbar-width:none;-webkit-overflow-scrolling:touch;touch-action:pan-x;overscroll-behavior-x:contain;padding:5px 1px 9px}
#pk-overlay .pk-font-tabs::-webkit-scrollbar,#pk-overlay .pk-fonts::-webkit-scrollbar,#pk-overlay .pk-color-rail::-webkit-scrollbar,#pk-overlay .pk-tpl-grid::-webkit-scrollbar{display:none}
#pk-overlay .pk-font-tabs button{flex:none!important;min-width:60px;white-space:nowrap;padding:8px 12px}
#pk-overlay .pk-fonts{display:flex!important;grid-template-columns:none!important;flex-wrap:nowrap!important;gap:9px!important;overflow-x:auto!important;overflow-y:hidden!important;touch-action:pan-x;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;scrollbar-width:none;padding:7px 3px 12px}
#pk-overlay .pk-fonts b{flex:none!important;width:118px!important;min-height:51px!important;padding:7px 8px!important;font-size:14px!important}
#pk-overlay .pk-color-rail{width:100%;display:flex;gap:10px;align-items:center;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch;scrollbar-width:none;touch-action:pan-x;overscroll-behavior-x:contain;padding:8px 3px 13px}
#pk-overlay .pk-color-rail button{flex:0 0 35px;width:35px;height:35px;padding:0;border-radius:50%;background:var(--pk-rail-color);border:1px solid rgba(0,0,0,.18);box-shadow:0 0 0 2px var(--pk-bg);cursor:pointer}
#pk-overlay .pk-color-rail button.on{outline:2px solid var(--pk-fg);outline-offset:2px}
#pk-overlay .pk-punch-suite{margin-top:10px}
#pk-overlay .pk-tpl-grid{display:flex!important;grid-template-columns:none!important;gap:11px!important;overflow-x:auto!important;overflow-y:hidden!important;white-space:nowrap;scrollbar-width:none;-webkit-overflow-scrolling:touch;touch-action:pan-x;overscroll-behavior-x:contain;padding:12px 4px 15px!important}
#pk-overlay .pk-tpl-grid .pk-tpl-card{position:relative!important;flex:0 0 53px!important;width:53px!important;min-width:53px!important;height:57px!important;padding:2px!important;border:0!important;background:transparent!important;box-shadow:none!important;overflow:visible!important;display:flex!important;align-items:flex-start!important;justify-content:center!important}
#pk-overlay .pk-palette-circle{display:block!important;width:46px!important;height:46px!important;flex:none;border-radius:50%;background:linear-gradient(90deg,var(--pk-half-one) 0 50%,var(--pk-half-two) 50% 100%);border:1px solid rgba(0,0,0,.12);box-shadow:0 1px 4px rgba(0,0,0,.08)}
#pk-overlay .pk-tpl-card .pk-tpl-del{position:absolute!important;right:-2px!important;top:-3px!important;z-index:2;display:flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:50%;background:var(--pk-bg);color:var(--pk-fg);font-size:13px}

/* v40: inline editing, without opening a separate editor view / overlay. */
#pk-overlay .pk-inline-actions{display:none;align-items:center;justify-content:space-between;gap:8px;width:100%;font-size:12px}
#pk-overlay.pk-inline-editing .pk-preview-tools .pk-main-tools,#pk-overlay.pk-inline-editing .pk-preview-tools .pk-zoom-tools{display:none!important}
#pk-overlay.pk-inline-editing .pk-preview-tools .pk-inline-actions{display:flex!important}
#pk-overlay .pk-inline-actions button{padding:8px 15px;border-radius:9px;border:1px solid var(--pk-line);background:var(--pk-bg);font:600 13px/1.2 inherit;cursor:pointer;touch-action:manipulation}
#pk-overlay .pk-inline-actions .pk-inline-done{background:var(--pk-fg);border-color:var(--pk-fg);color:var(--pk-bg)}
#pk-overlay.pk-inline-editing .pk-stage{overflow:auto!important}
#pk-overlay.pk-inline-editing .pk-edta{display:block!important;z-index:5!important;box-shadow:none!important;outline:1px solid rgba(95,110,130,.25);outline-offset:0;-webkit-user-select:text!important;user-select:text!important;-webkit-touch-callout:default!important;cursor:text}
#pk-overlay.css-active.pk-inline-editing .pk-edta{display:none!important;visibility:hidden!important;pointer-events:none!important}
#pk-overlay.css-active.pk-inline-editing .pk-css-holder{pointer-events:auto!important}
#pk-overlay .pk-css-holder .pk-css-page [data-pk=body][contenteditable=true]{-webkit-user-select:text!important;user-select:text!important;-webkit-touch-callout:default!important;outline:1px dashed #9ba6b8;outline-offset:4px;cursor:text!important;min-height:1.5em;white-space:pre-wrap}
#pk-overlay.pk-inline-editing .pk-css-page .pa-body[contenteditable=true],#pk-overlay.pk-inline-editing .pk-css-page .im-bubble[contenteditable=true]{-webkit-user-select:text!important;user-select:text!important;-webkit-touch-callout:default!important;cursor:text!important;outline:1px dashed #9ba6b8!important;outline-offset:3px;min-height:1.4em}
#pk-overlay.pk-inline-editing .pk-preview-tools{min-height:50px}
@media(max-width:440px){#pk-overlay .pk-inline-actions span{font-size:11px;color:var(--pk-mute)}}

#pk-overlay .pk-saving{opacity:.5;pointer-events:none}

/* v35: direct home actions. */
#pk-overlay .pk-main-tools{display:flex;gap:8px;align-items:center;justify-content:flex-end;flex-wrap:wrap}
#pk-overlay .pk-main-tools .pk-tool{min-width:auto;padding:0 12px;gap:7px}
#pk-overlay .pk-main-tools .pk-tool span{display:inline}
#pk-overlay .pk-main-tools .pk-settings-tool{min-width:auto}

#pk-overlay [data-threads-options][hidden],#pk-overlay [data-threads-comment-fields][hidden]{display:none!important}#pk-overlay [data-threads-comment-fields]{padding-left:12px;border-left:2px solid var(--pk-line);margin:5px 0 6px 3px}#pk-overlay [data-threads-comment-fields] .pk-row{max-width:100%}

